export function redactAudit(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(redactAudit);
  }

  if (!isPlainObject(value)) {
    return value;
  }

  const copy: Record<string, unknown> = Object.create(
    Object.getPrototypeOf(value),
  );

  for (const [key, nestedValue] of Object.entries(value)) {
    copy[key] = isSensitiveKey(key)
      ? '[REDACTED]'
      : redactAudit(nestedValue);
  }

  return copy;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== 'object') {
    return false;
  }

  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function isSensitiveKey(key: string): boolean {
  return /^(password|token|secret)$/i.test(key);
}

